def solve(payload):
    ss = payload["segments"]
    if not ss or any(s[k] <= 0 for s in ss for k in ("length_m", "area_m2", "young_pa")):
        return {"error": "invalid_segment"}
    free = [s["alpha_per_k"]*s["delta_temp_k"]*s["length_m"] for s in ss]
    compliance = [s["length_m"]/(s["area_m2"]*s["young_pa"]) for s in ss]
    force = (payload["imposed_extension_m"]-sum(free))/sum(compliance)
    return {"force_n": force, "segment_extensions_m": [f+force*c for f, c in zip(free, compliance)]}

